function setupServiceWorkerUpdates(){if(!("serviceWorker"in navigator))return;const notice=$("#updateNotice"),show=()=>notice.classList.remove("hidden");let refreshing=false,registrationRef=null;const inspectedWorkers=new WeakSet();const inspect=registration=>{if(registration.waiting&&navigator.serviceWorker.controller)show();const worker=registration.installing;if(worker&&!inspectedWorkers.has(worker)){inspectedWorkers.add(worker);worker.addEventListener("statechange",()=>{if(worker.state==="installed"&&navigator.serviceWorker.controller)show()})}};const check=()=>{if(!registrationRef||document.visibilityState!=="visible")return;registrationRef.update().then(()=>inspect(registrationRef)).catch(()=>{})};navigator.serviceWorker.addEventListener("controllerchange",()=>{if(refreshing)return;refreshing=true;window.location.reload()});navigator.serviceWorker.register("service-worker.js",{updateViaCache:"none"}).then(registration=>{registrationRef=registration;registration.addEventListener("updatefound",()=>inspect(registration));inspect(registration);check();setInterval(check,5*60*1000);document.addEventListener("visibilitychange",check);window.addEventListener("pageshow",check);window.addEventListener("focus",check);window.addEventListener("online",check)}).catch(()=>{});$("#applyUpdateBtn").onclick=()=>{navigator.serviceWorker.getRegistration().then(reg=>{if(reg?.waiting)reg.waiting.postMessage({type:"SKIP_WAITING"});else window.location.reload()})};$("#dismissUpdateBtn").onclick=()=>notice.classList.add("hidden")}
