function openBookForm(b=null){stopISBNScanner();$("#bookForm").reset();$("#isbnStatus").textContent="";$("#bookId").value=b?.id||"";$("#bookDialogTitle").textContent=b?"Editar libro":"Añadir libro";["title","author","publisher","year","edition","isbn","totalPages","currentPage","status","coverUrl"].forEach(k=>$("#"+k).value=b?.[({title:"title",author:"author",publisher:"publisher",year:"year",edition:"edition",isbn:"isbn",totalPages:"totalPages",currentPage:"currentPage",status:"status",coverUrl:"coverUrl"})[k]]??(k==="status"?"pending":k==="currentPage"?0:""));coverData=b?.cover||null;$("#catalogPanel").classList.add("hidden");$("#manualMode").classList.add("active");$("#searchMode").classList.remove("active");$("#bookDialog").showModal()}
