function normalizeISBN(value){const isbn=String(value||"").replace(/[^0-9x]/gi,"").toUpperCase();if(/^\d{13}$/.test(isbn)){const sum=[...isbn.slice(0,12)].reduce((n,d,i)=>n+Number(d)*(i%2?3:1),0);return (10-sum%10)%10===Number(isbn[12])?isbn:null}if(/^\d{9}[0-9X]$/.test(isbn)){const sum=[...isbn].reduce((n,d,i)=>n+(d==="X"?10:Number(d))*(10-i),0);return sum%11===0?isbn:null}return null}
async function lookupISBN(value){const isbn=normalizeISBN(value);if(!isbn){$("#isbnStatus").textContent="Ingresá o escaneá un ISBN-10 o ISBN-13 válido.";return}$("#isbn").value=isbn;$("#isbnStatus").textContent="Buscando el libro por ISBN…";try{const url="https://openlibrary.org/search.json?q="+encodeURIComponent("isbn:"+isbn)+"&fields=title,author_name,publisher,first_publish_year,number_of_pages_median,cover_i,isbn&limit=1";const response=await fetch(url);if(!response.ok)throw Error("No se pudo consultar el catálogo.");const data=await response.json(),book=data.docs?.[0];if(!book){$("#isbnStatus").textContent="No encontré datos para ese ISBN. Podés completar la ficha manualmente.";return}$("#title").value=book.title||"";$("#author").value=(book.author_name||[]).join(", ");$("#publisher").value=(book.publisher||[])[0]||"";$("#year").value=book.first_publish_year||"";$("#totalPages").value=book.number_of_pages_median||"";$("#isbn").value=(book.isbn||[]).find(x=>normalizeISBN(x))||isbn;if(book.cover_i)$("#coverUrl").value=`https://covers.openlibrary.org/b/id/${book.cover_i}-L.jpg`;$("#isbnStatus").textContent="Datos encontrados. Revisá la edición y completá lo que falte antes de guardar."}catch(err){$("#isbnStatus").textContent="No hubo conexión con el catálogo. El ISBN quedó cargado; podés completar los datos manualmente."}}
