$("#scanIsbnBtn").onclick=async()=>{const status=$("#isbnStatus");if(!("BarcodeDetector" in window)){status.textContent="Este navegador no admite escaneo de códigos. Escribí el ISBN y tocá Buscar.";return}if(!navigator.mediaDevices?.getUserMedia){status.textContent="No se puede abrir la cámara en este contexto. Escribí el ISBN y tocá Buscar.";return}try{const supported=await BarcodeDetector.getSupportedFormats(),formats=["ean_13","ean_8","upc_a","upc_e"].filter(x=>supported.includes(x));if(!formats.length)throw Error("No hay formatos de código compatibles.");const detector=new BarcodeDetector({formats});isbnScannerStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:"environment"}},audio:false});const video=$("#isbnVideo");video.srcObject=isbnScannerStream;$("#isbnScanner").classList.remove("hidden");status.textContent="Apuntá la cámara al código de barras del libro.";await video.play();const scan=async()=>{if(!isbnScannerStream)return;try{const codes=await detector.detect(video),code=codes.find(x=>x.rawValue);if(code){const isbn=normalizeISBN(code.rawValue);stopISBNScanner();if(!isbn){status.textContent="El código leído no parece un ISBN válido. Probá encuadrar el código EAN de la contratapa.";return}$("#isbn").value=isbn;await lookupISBN(isbn);return}}catch{}if(isbnScannerStream)setTimeout(scan,140)};scan()}catch(err){stopISBNScanner();status.textContent=err.name==="NotAllowedError"?"No se concedió acceso a la cámara. Podés escribir el ISBN manualmente.":"No se pudo iniciar el escáner. Escribí el ISBN y tocá Buscar."}};
