if(detailTab==="notes"){let ordered=notes.sort((a,b)=>(a.section||1)-(b.section||1)||(a.number||0)-(b.number||0)),lastSection=0;const noteRows=ordered.map(n=>{const section=n.section||1,heading=section!==lastSection?`<h3 class="note-section">Sección ${section}</h3>`:"";lastSection=section;return `${heading}<div class="note-row ${n.read?"read":""}" data-ai-note="${n.id}"><div class="note-num">${esc(n.number)}</div><button type="button" class="note-body note-read-toggle" data-toggle-note="${n.id}" aria-pressed="${n.read}" title="${n.read?"Marcar como no leída":"Marcar como leída"}"><strong>Nota ${esc(n.number)}</strong><small> · ${n.referencePage!=null?"Referencia p. "+n.referencePage:"Sin página de referencia"}${n.endPage!=null?" · Nota p. "+n.endPage:""}</small><p>${esc(n.text)}</p>${n.comment?`<p class="note-comment"><strong>Mi comentario:</strong> ${esc(n.comment)}</p>`:""}</button><div class="note-actions"><button type="button" class="ask-gemini" data-ask-note="${n.id}" title="Preguntar a la IA sobre esta nota">Preguntar a la IA</button><button type="button" class="comment-note-btn" data-comment-note="${n.id}" title="Comentar nota">${n.comment?"Editar comentario":"＋ Comentario"}</button><button data-delete-note="${n.id}" title="Eliminar" aria-label="Eliminar nota ${esc(n.number)}">×</button></div></div>`}).join("");p.innerHTML=`<div class="content-heading"><div><h2>Notas finales</h2><p class="muted">${read} de ${notes.length} leídas · Tocá una nota para marcarla · mantenela apretada (o clic derecho) para preguntarle a la IA.</p></div><button class="primary" id="addManualNote">＋ Añadir nota</button></div>${noteRows||'<p class="empty-inline">Todavía no hay notas. Podés agregar una desde acá o importar un JSON en Ajustes.</p>'}`}
if(detailTab==="entries"||detailTab==="photos"){let filtered=entries.filter(x=>detailTab==="entries"||x.photo);p.innerHTML=`<div class="content-heading"><div><h2>${detailTab==="entries"?"Anotaciones":"Fotografías"}</h2><p class="muted">${filtered.length} ${detailTab==="entries"?"registros":"fotografías"} · Mantené apretada una para preguntarle a la IA (o clic derecho).</p></div><button class="primary" id="addAnnotation">＋ Nueva anotación</button></div>${filtered.map(x=>`<article class="journal-item" data-ai-entry="${x.id}"><small>PÁGINA ${x.page} · ${new Date(x.createdAt).toLocaleDateString("es-AR")}</small><h3>${esc(x.title||"Sin título")}</h3><p>${esc(x.text||"")}</p>${x.photo?`<img class="annotation-photo-thumb" data-open-photo="${x.id}" src="${x.photo}" alt="Abrir fotografía">`:""}<div class="annotation-actions"><button class="mini" data-edit-entry="${x.id}">Editar anotación</button><button class="mini" data-ask-entry="${x.id}">Preguntar a la IA</button><button class="mini" data-delete-entry="${x.id}">Eliminar</button></div></article>`).join("")||`<p class="empty-inline">Todavía no hay ${detailTab==="entries"?"anotaciones":"fotografías"}.</p>`}`}
